// Differential tests: parseEmail() against parsedmarc's parse_email() output,
// generated by tools/fixtures/generate_email.py for every .eml in samples/,
// the failure-report samples inside them and the hand-made edge cases in
// __fixtures__/email/cases.

import { readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

import { describe, expect, it } from 'vitest';

import { toSnakeCaseKeys } from '../serialize';
import { parseEmail } from './email';

const FIXTURES = path.resolve(import.meta.dirname, '__fixtures__', 'email');
const ROOT = path.resolve(import.meta.dirname, '..', '..', '..', '..');

interface Fixture {
  input: string;
  result?: Record<string, unknown>;
  error?: { type: string; message: string };
}

const RANDOM_FILENAME = /^[a-z]{10}\.(txt|rtf)$/u;

// Python iterates sets in hash order and names some attachments randomly;
// normalize both before comparing.
function normalize(value: unknown): unknown {
  const parsed = JSON.parse(JSON.stringify(value)) as Record<string, unknown>;
  for (const key of ['to_domains', 'defects_categories']) {
    const list = parsed[key];
    if (Array.isArray(list)) {
      parsed[key] = list.toSorted();
    }
  }
  const attachments = parsed.attachments;
  if (Array.isArray(attachments)) {
    for (const attachment of attachments as Record<string, unknown>[]) {
      for (const key of ['filename', 'safe_filename']) {
        const name = attachment[key];
        if (typeof name === 'string' && RANDOM_FILENAME.test(name)) {
          attachment[key] = name.replace(/^[a-z]{10}/u, '<random>');
        }
      }
    }
  }
  return parsed;
}

function inputPath(input: string): string {
  return input.startsWith('samples/')
    ? path.join(ROOT, input)
    : path.join(FIXTURES, input);
}

const fixtureFiles = readdirSync(path.join(FIXTURES, 'expected')).filter(name =>
  name.endsWith('.json'),
);

describe('parseEmail matches parsedmarc parse_email()', () => {
  it('has fixtures', () => {
    expect(fixtureFiles.length).toBeGreaterThan(30);
  });

  it.each(fixtureFiles)('%s', async name => {
    const fixture = JSON.parse(
      readFileSync(path.join(FIXTURES, 'expected', name), 'utf8'),
    ) as Fixture;
    const data = new Uint8Array(readFileSync(inputPath(fixture.input)));
    const stripAttachmentPayloads = name.endsWith('.stripped.json');
    if (fixture.error !== undefined) {
      await expect(
        parseEmail(data, { stripAttachmentPayloads }),
      ).rejects.toThrow(fixture.error.message);
      return;
    }
    const parsed = await parseEmail(data, { stripAttachmentPayloads });
    expect(normalize(toSnakeCaseKeys(parsed))).toEqual(
      normalize(fixture.result),
    );
  });
});
